from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

@app.get("/headers")
async def read_headers(my_header: str = Header(None)):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_not_accepted():
    # Default convert_underscores=True. 
    # Should accept 'my-header'
    response = client.get("/headers", headers={"my-header": "hello"})
    assert response.json() == {"my_header": "hello"}

    # Should NOT accept 'my_header'
    # Currently it probably does.
    response = client.get("/headers", headers={"my_header": "world"})
    # If it's not accepted, it should be None (since default is None)
    assert response.json() == {"my_header": None}

def test_underscore_header_accepted_when_disabled():
    # Explicitly disable convert_underscores
    @app.get("/headers_disabled")
    async def read_headers_disabled(my_header: str = Header(None, convert_underscores=False)):
        return {"my_header": my_header}

    response = client.get("/headers_disabled", headers={"my_header": "world"})
    assert response.json() == {"my_header": "world"}

if __name__ == "__main__":
    try:
        test_underscore_header_not_accepted()
        print("test_underscore_header_not_accepted passed")
